// Kyung Hee University, Seoul Campus (경희대 서울캠퍼스, 회기동). Data is generated by scripts/campuses/kyunghee/build-package.mjs from the
// pilot (pilot/kyunghee-seoul, round 3): 28 destructible buildings (본관·평화의전당·중앙도서관·크라운관 detailed, 정문 등용문 custom,
// 23 generic), the five 경희의료원 hospital models as protected (shield, never damaged), a baked ground with the pilot's ground shader
// (the SKKU port src/campuses/skku/ground-look.js, fed with this campus's look and zone mask), the formal landscape of the
// 정문 -> 교시탑 -> 분수 -> 본관 axis, and the non-destructible context (회기동·이문동, 천장산, HUFS massing) fading into the haze.
// Local only until the user approves (registry public: false).
import { WORLD_UNITS_PER_METER, GEO_ORIGIN, KH_PLACEMENTS, KH_BUILDING_BASE, KH_HEIGHT_GRIDS, KH_HEIGHT_RANGE_M, KH_ENV_IDS, KH_ENV_MANIFEST_IDS, KH_LOOK, KH_ZONES, KH_PROVENANCE } from './data.js';
import { KH_FOOTPRINTS } from './footprints.js';
import { KH_PROTECTED } from './protected.js';
import { createSkkuGroundLook } from '../skku/ground-look.js';

const MODEL_IDS = Object.freeze(KH_PLACEMENTS.map(p => p.id));
const asset = file => new URL(`../../../assets/campuses/kyunghee/${file}`, import.meta.url).href;
const HAZE = '#dde5e8';

export const KYUNGHEE = Object.freeze({
  id: 'kyunghee',
  meta: Object.freeze({ school: '경희대학교', campus: '서울캠퍼스', short: '경희대 서울', modelNoun: '경희대' }),
  geo: Object.freeze({ origin: GEO_ORIGIN, worldUnitsPerMeter: WORLD_UNITS_PER_METER }),
  placements: KH_PLACEMENTS,
  approvedCount: KH_PLACEMENTS.length,
  additionalCount: 0,
  coreIds: Object.freeze(['main', 'peaceHall', 'library', 'music', 'mainGate']),
  startBuildingId: 'main',
  // Start: the fountain axis toward 본관 (분수 광장 in front, the portico and grand stair at the end of the axis, 평화의전당 towers
  // beyond on the right). World units (metres x 0.5, z = -N); azimuth = the 교시탑 -> 분수 -> 본관 axis seen from the south-south-east.
  view: Object.freeze({ startFrame: Object.freeze({ min: Object.freeze([-27, -1, -42]), max: Object.freeze([12, 14, 8]), azimuth: 0.4 }) }),
  models: Object.freeze({
    manifests: Object.freeze([
      Object.freeze({ url: asset('manifest.json'), expectedIds: MODEL_IDS }),
      Object.freeze({ url: asset('environment.json'), expectedIds: KH_ENV_MANIFEST_IDS }),
    ]),
    proceduralIds: Object.freeze([]),
    createProceduralSource: () => { throw new Error('No procedural buildings in this campus'); },
    enhanceFacade: () => ({ stats: {}, dispose() {} }),
  }),
  terrain: Object.freeze({ heightGrids: KH_HEIGHT_GRIDS, buildingBase: KH_BUILDING_BASE,
    source: 'Relative terrain estimate (SRTM, building-filled, canopy lowered by an estimate + floor-link evidence, pilot/kyunghee-seoul); not a survey' }),
  environment: Object.freeze({ provenance: KH_PROVENANCE, sourceNote: 'OSM ground surfaces and surroundings (© OpenStreetMap contributors, ODbL); heights, planting and the formal landscape estimated' }),
  ground: Object.freeze({
    baked: Object.freeze({ envIds: KH_ENV_IDS, castShadow: Object.freeze([]), materialHook: createSkkuGroundLook(KH_LOOK, KH_ZONES),
      fade: Object.freeze({ centre_m: Object.freeze([116.53, -81.29]), near_m: 520, far_m: 1250, colour: HAZE }), playMargin_m: 30,
      source: 'pilot/kyunghee-seoul preview ground + landscape + context, baked' }),
  }),
  // 경희의료원 (hospitals): never destructible; weapons meet the protective shield (src/protected-buildings.js), own small cache.
  protected: Object.freeze({
    manifestURL: asset('protected/manifest.json'),
    models: KH_PROTECTED,
  }),
  // Hazard tape around every destructible building only (src/engine/hazard-tape.js): none on the hospitals or the context.
  hazardTape: Object.freeze({ footprints: KH_FOOTPRINTS }),
  scene: Object.freeze({
    background: HAZE, fog: Object.freeze({ color: HAZE, near: 700, far: 2200 }),
    hemisphere: Object.freeze({ sky: '#eef2f4', ground: '#7d8a78', intensity: 1.3 }),
    sun: Object.freeze({ color: '#fff4e2', intensity: 2.9, position: Object.freeze([-150, 200, 100]), shadowSpan: 230 }),
    floor: Object.freeze({ color: '#c9cbc8', hidden: true, y: KH_HEIGHT_RANGE_M[0] * WORLD_UNITS_PER_METER - .3 }),
  }),
});
export default KYUNGHEE;
